import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    n, k = read_ints()
    parents = [0] + read_ints()

    # Create adjacency list for the tree
    adj_list = defaultdict(list)
    for i in range(2, n + 1):
        adj_list[parents[i]].append(i)

    # Calculate depth of each node
    depth = [0] * (n + 1)
    for i in range(2, n + 1):
        depth[i] = depth[parents[i]] + 1

    # Find all leaves
    leaves = []
    for i in range(2, n + 1):
        if len(adj_list[i]) == 0:
            leaves.append(i)

    # BFS to find the maximum number of different leaves
    max_leaves = 0
    for leaf in leaves:
        visited = set()
        queue = deque([(leaf, 0)])
        while queue:
            node, dist = queue.popleft()
            if dist > k:
                break
            if node != 1 and len(adj_list[node]) == 1:  # If node is a leaf
                visited.add(node)
            for child in adj_list[node]:
                queue.append((child, dist + 1))
        max_leaves = max(max_leaves, len(visited))

    print(max_leaves)

